import{_ as o,a0 as l,w as u,s as d,ao as p,I as i,x as n,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"如何禁用 Ubuntu 服务器中终端欢迎消息中的广告 | LCTT x X-CMD","titleTemplate":false,"description":"如何禁用 Ubuntu 服务器中终端欢迎消息中的广告 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何禁用 Ubuntu 服务器中终端欢迎消息中的广告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何禁用 Ubuntu 服务器中终端欢迎消息中的广告 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server","title":"如何禁用 Ubuntu 服务器中终端欢迎消息中的广告","tag":"201811","desc":""},"relativePath":"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server.md","filePath":"[post].md"}'),r={name:"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server.md"};function c(m,s,b,h,g,f){const e=l("Link");return u(),d("div",null,[s[20]||(s[20]=p('<h1 id="如何禁用-ubuntu-服务器中终端欢迎消息中的广告" tabindex="-1">如何禁用 Ubuntu 服务器中终端欢迎消息中的广告 <a class="header-anchor" href="#如何禁用-ubuntu-服务器中终端欢迎消息中的广告" aria-label="Permalink to “如何禁用 Ubuntu 服务器中终端欢迎消息中的广告”">​</a></h1><p>如果你正在使用最新的 Ubuntu 服务器版本，你可能已经注意到欢迎消息中有一些与 Ubuntu 服务器平台无关的促销链接。你可能已经知道 <strong>MOTD</strong>，即 <strong>M</strong>essage <strong>O</strong>f <strong>T</strong>he <strong>D</strong>ay 的开头首字母，在 Linux 系统每次登录时都会显示欢迎信息。通常，欢迎消息包含操作系统版本，基本系统信息，官方文档链接以及有关最新安全更新等的链接。这些是我们每次通过 SSH 或本地登录时通常会看到的内容。但是，最近在终端欢迎消息中出现了一些其他链接。我已经几次注意到这些链接，但我并在意，也从未点击过。以下是我的 Ubuntu 18.04 LTS 服务器上显示的终端欢迎消息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Ubuntu-Terminal-welcome-message.png" alt=""></p>',3)),i("p",null,[s[2]||(s[2]=n("正如你在上面截图中所看到的，欢迎消息中有一个 bit.ly 链接和 Ubuntu wiki 链接。有些人可能会惊讶并想知道这是什么。其实欢迎信息中的链接无需担心。它可能看起来像广告，但并不是商业广告。链接实际上指向到了 ",-1)),t(e,{href:"https://blog.ubuntu.com/"},{default:a(()=>[...s[0]||(s[0]=[n("Ubuntu 官方博客",-1)])]),_:1}),s[3]||(s[3]=n(" 和 ",-1)),t(e,{href:"https://wiki.ubuntu.com/"},{default:a(()=>[...s[1]||(s[1]=[n("Ubuntu wiki",-1)])]),_:1}),s[4]||(s[4]=n("。正如我之前所说，其中的一个链接是不相关的，没有任何与 Ubuntu 服务器相关的细节，这就是为什么我开头称它们为广告。",-1))]),s[21]||(s[21]=p(`<p>虽然我们大多数人都不会访问 bit.ly 链接，但是有些人可能出于好奇去访问这些链接，结果失望地发现它只是指向一个外部链接。你可以使用任何 URL 去短网址服务，例如 unshorten.it，在访问真正链接之前，查看它会指向哪里。或者，你只需在 bit.ly 链接的末尾输入加号（<code>+</code>）即可查看它们的实际位置以及有关链接的一些统计信息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/shortlink.png" alt=""></p><h3 id="什么是-motd-以及它是如何工作的" tabindex="-1">什么是 MOTD 以及它是如何工作的？ <a class="header-anchor" href="#什么是-motd-以及它是如何工作的" aria-label="Permalink to “什么是 MOTD 以及它是如何工作的？”">​</a></h3><p>2009 年，来自 Canonical 的 Dustin Kirkland 在 Ubuntu 中引入了 MOTD 的概念。它是一个灵活的框架，使管理员或发行包能够在 <code>/etc/update-motd.d/</code> 位置添加可执行脚本，目的是生成在登录时显示有益的、有趣的消息。它最初是为 Landscape（Canonical 的商业服务）实现的，但是其它发行版维护者发现它很有用，并且在他们自己的发行版中也采用了这个特性。</p><p>如果你在 Ubuntu 系统中查看 <code>/etc/update-motd.d/</code>，你会看到一组脚本。一个是打印通用的 “欢迎” 横幅。下一个打印 3 个链接，显示在哪里可以找到操作系统的帮助。另一个计算并显示本地系统包可以更新的数量。另一个脚本告诉你是否需要重新启动等等。</p><p>从 Ubuntu 17.04 起，开发人员添加了 <code>/etc/update-motd.d/50-motd-news</code>，这是一个脚本用来在欢迎消息中包含一些附加信息。这些附加信息是：</p><ol><li>重要的关键信息，例如 ShellShock、Heartbleed 等</li><li>生命周期（EOL）消息，新功能可用性等</li><li>在 Ubuntu 官方博客和其他有关 Ubuntu 的新闻中发布的一些有趣且有益的帖子</li></ol><p>另一个特点是异步，启动后约 60 秒，systemd 计时器运行 <code>/etc/update-motd.d/50-motd-news –force</code> 脚本。它提供了 <code>/etc/default/motd-news</code> 脚本中定义的 3 个配置变量。默认值为：<code>ENABLED=1, URLS=&quot;https://motd.ubuntu.com&quot;, WAIT=&quot;5&quot;</code>。</p><p>以下是 <code>/etc/default/motd-news</code> 文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/default/motd-news</span></span>
<span class="line"><span># Enable/disable the dynamic MOTD news service</span></span>
<span class="line"><span># This is a useful way to provide dynamic, informative</span></span>
<span class="line"><span># information pertinent to the users and administrators</span></span>
<span class="line"><span># of the local system</span></span>
<span class="line"><span>ENABLED=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Configure the source of dynamic MOTD news</span></span>
<span class="line"><span># White space separated list of 0 to many news services</span></span>
<span class="line"><span># For security reasons, these must be https</span></span>
<span class="line"><span># and have a valid certificate</span></span>
<span class="line"><span># Canonical runs a service at motd.ubuntu.com, and you</span></span>
<span class="line"><span># can easily run one too</span></span>
<span class="line"><span>URLS=&quot;https://motd.ubuntu.com&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Specify the time in seconds, you&#39;re willing to wait for</span></span>
<span class="line"><span># dynamic MOTD news</span></span>
<span class="line"><span># Note that news messages are fetched in the background by</span></span>
<span class="line"><span># a systemd timer, so this should never block boot or login</span></span>
<span class="line"><span>WAIT=5</span></span></code></pre></div><p>好事情是 MOTD 是完全可定制的，所以你可以彻底禁用它（<code>ENABLED=0</code>）、根据你的意愿更改或添加脚本、以秒为单位更改等待时间等等。</p><p>如果启用了 MOTD，那么 systemd 计时器作业将循环遍历每个 URL，将它们的内容缩减到每行 80 个字符、最多 10 行，并将它们连接到 <code>/var/cache/motd-news</code> 中的缓存文件。此 systemd 计时器作业将每隔 12 小时运行并更新 <code>/var/cache/motd-news</code>。用户登录后，<code>/var/cache/motd-news</code> 的内容会打印到屏幕上。这就是 MOTD 的工作原理。</p><p>此外，<code>/etc/update-motd.d/50-motd-news</code> 文件中包含自定义的用户代理字符串，以报告有关计算机的信息。如果你查看 <code>/etc/update-motd.d/50-motd-news</code> 文件，你会看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Piece together the user agent</span></span>
<span class="line"><span>USER_AGENT=&quot;curl/$curl_ver $lsb $platform $cpu $uptime&quot;</span></span></code></pre></div><p>这意味着，MOTD 检索器将向 Canonical 报告你的操作系统版本、硬件平台、CPU 类型和正常运行时间。</p><p>到这里，希望你对 MOTD 有了一个基本的了解。</p><p>现在让我们回到主题，我不想要这个功能。我该如何禁用它？如果欢迎消息中的促销链接仍然困扰你，并且你想永久禁用它们，则可以通过以下方法快速禁用它。</p><h3 id="在-ubuntu-服务器中禁用终端欢迎消息中的广告" tabindex="-1">在 Ubuntu 服务器中禁用终端欢迎消息中的广告 <a class="header-anchor" href="#在-ubuntu-服务器中禁用终端欢迎消息中的广告" aria-label="Permalink to “在 Ubuntu 服务器中禁用终端欢迎消息中的广告”">​</a></h3><p>要禁用这些广告，编辑文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/default/motd-news</span></span></code></pre></div><p>找到以下行并将其值设置为 <code>0</code>（零）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>ENABLED=0</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>保存并关闭文件。现在，重新启动系统，看看欢迎消息是否仍然显示来自 Ubuntu 博客的链接。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/Ubuntu-Terminal-welcome-message-1.png" alt=""></p><p>看到没？现在没有来自 Ubuntu 博客和 Ubuntu wiki 的链接。</p><p>这就是全部内容了。希望这对你有所帮助。更多好东西要来了，敬请关注！</p><p>顺祝时祺！</p><hr>`,28)),i("p",null,[s[6]||(s[6]=n("via: ",-1)),t(e,{href:"https://www.ostechnix.com/how-to-disable-ads-in-terminal-welcome-message-in-ubuntu-server/"},{default:a(()=>[...s[5]||(s[5]=[n("https://www.ostechnix.com/how-to-disable-ads-in-terminal-welcome-message-in-ubuntu-server/",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=n("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[7]||(s[7]=[n("SK",-1)])]),_:1}),s[12]||(s[12]=n(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),t(e,{href:"https://github.com/MjSeven"},{default:a(()=>[...s[9]||(s[9]=[n("MjSeven",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const U=o(r,[["render",c]]);export{k as __pageData,U as default};
